// Scoreboard (uvm_scoreboard)
// ════════════════════════════════════════════════════════════

class fsm_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(fsm_scoreboard)

  uvm_analysis_imp #(fsm_seq_item, fsm_scoreboard) item_collected_export;

  typedef enum logic [2:0] {S0=0, S1=1, S2=2, S3=3, SR=4} state_e;

  state_e exp_state;
  bit initialized = 0;

  function new(string name = "fsm_scoreboard", uvm_component parent = null);
    super.new(name, parent);
    item_collected_export = new("item_collected_export", this);
  endfunction

 virtual function void write(fsm_seq_item tx);
  logic [1:0] exp_NS;
  logic [1:0] exp_EW;

  // First observed reset establishes known model state.
  if (!initialized) begin
    if (tx.reset) begin
      initialized = 1;
      exp_state = SR;
    end else begin
      return;
    end
  end

  // When reset is asserted, the DUT's async reset forces outputs to 00/00
  // immediately, regardless of what state we last modeled. Match that behavior.
  if (tx.reset) begin
    exp_NS = 2'b00;
    exp_EW = 2'b00;
  end else begin
    case (exp_state)
      S0: begin exp_NS = 2'b10; exp_EW = 2'b00; end
      S1: begin exp_NS = 2'b01; exp_EW = 2'b00; end
      S2: begin exp_NS = 2'b00; exp_EW = 2'b10; end
      S3: begin exp_NS = 2'b00; exp_EW = 2'b01; end
      SR: begin exp_NS = 2'b00; exp_EW = 2'b00; end
      default: begin exp_NS = 2'b00; exp_EW = 2'b00; end
    endcase
  end

  if (tx.light_NS !== exp_NS || tx.light_EW !== exp_EW) begin
    `uvm_error("SCB_FAIL",
      $sformatf("State:%s Exp NS:%0b EW:%0b | Act NS:%0b EW:%0b reset=%0b",
                exp_state.name(), exp_NS, exp_EW,
                tx.light_NS, tx.light_EW, tx.reset))
  end else begin
    `uvm_info("SCB_PASS",
      $sformatf("State:%s matched NS:%0b EW:%0b reset=%0b",
                exp_state.name(), tx.light_NS, tx.light_EW, tx.reset),
                UVM_HIGH)
  end

  // Advance state for the next sample.
  if (tx.reset) begin
    exp_state = SR;
  end else begin
    case (exp_state)
      SR: exp_state = S0;
      S0: exp_state = S1;
      S1: exp_state = S2;
      S2: exp_state = S3;
      S3: exp_state = S0;
      default: exp_state = S0;
    endcase
  end
endfunction
endclass

