// Functional Coverage (uvm_subscriber)
// ════════════════════════════════════════════════════════════

class fsm_coverage extends uvm_subscriber #(fsm_seq_item);
  `uvm_component_utils(fsm_coverage)

  fsm_seq_item tx;

  covergroup cg_fsm;
    option.per_instance = 1;

    cp_reset: coverpoint tx.reset {
      bins reset_asserted   = {1};
      bins reset_deasserted = {0};
    }

    cp_NS: coverpoint tx.light_NS {
      bins red    = {2'b00};
      bins yellow = {2'b01};
      bins green  = {2'b10};
    }

    cp_EW: coverpoint tx.light_EW {
      bins red    = {2'b00};
      bins yellow = {2'b01};
      bins green  = {2'b10};
    }

    // Capture standard progression through lights
    cp_NS_trans: coverpoint tx.light_NS {
      bins ns_g_y_r = (2'b10 => 2'b01 => 2'b00);
    }

    cp_EW_trans: coverpoint tx.light_EW {
      bins ew_g_y_r = (2'b10 => 2'b01 => 2'b00);
    }

    // Cross combinations to ensure only safe/valid pairs are generated
    cross_lights: cross cp_NS, cp_EW {
      ignore_bins invalid_both_green = binsof(cp_NS.green) && binsof(cp_EW.green);
      ignore_bins invalid_both_yellow = binsof(cp_NS.yellow) && binsof(cp_EW.yellow);
    }
  endgroup

  function new(string name = "fsm_coverage", uvm_component parent = null);
    super.new(name, parent);
    cg_fsm = new();
  endfunction

  virtual function void write(fsm_seq_item t);
    $cast(tx, t.clone());
    cg_fsm.sample();
  endfunction
endclass

